return $input.all().map(item => {
  const e = item.json;
  const startObj = e.start || {};
  const endObj = e.end || {};

  return {
    json: {
      record_type: 'meeting',
      event_id: e.id || '',
      meeting_title: e.summary || '',
      organizer_email: (e.organizer?.email || '').toLowerCase().trim(),
      start_time: startObj['dateTime'] ?? startObj['date'] ?? '',
      end_time: endObj['dateTime'] ?? endObj['date'] ?? '',
      location: e.location || '',
      status: e.status || '',
      attendees: e.attendees || []
    }
  };
});

const contacts = $input.all().map(i => i.json);

const emails = contacts
  .map(c => (c.contact_email || '').trim().toLowerCase())
  .filter(Boolean);

const uniqueEmails = [...new Set(emails)];

// keep query size reasonable
const limitedEmails = uniqueEmails.slice(0, 20);

const emailQueryPart = limitedEmails.join(' OR ');

return [
  {
    json: {
      gmail_query_dynamic: emailQueryPart
        ? `(${emailQueryPart}) newer_than:30d`
        : 'newer_than:30d'
    }
  }
];

const contacts = $('Normalize Contacts').all().map(i => i.json);
const accounts = $('Normalize Accounts').all().map(i => i.json);
const opportunities = $('Normalize Opportunities').all().map(i => i.json);
const emails = $('Normalize Emails').all().map(i => i.json);
const meetings = $('Normalize Meetings').all().map(i => i.json);
function splitEmails(input) {
  if (!input) return [];

  return [...new Set(
    String(input)
      .split(',')
      .map(v => v.trim())
      .filter(Boolean)
      .map(v => v.replace(/^(to|from|cc|bcc):\s*/i, '').trim()) 
      .map(v => {
        const match = v.match(/<([^>]+)>/);
        return (match ? match[1] : v).toLowerCase().trim();
      })
  )];
}

function normalizeAttendees(attendees) {
  if (!Array.isArray(attendees)) return [];
  return [...new Set(
    attendees
      .map(a => typeof a === 'string' ? a : a?.email)
      .filter(Boolean)
      .map(v => String(v).toLowerCase().trim())
  )];
}

function extractDomainFromAccountName(name = '') {
  return String(name || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function parseDateSafe(v) {
  if (!v) return null;
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

const accountById = new Map(
  accounts.map(a => [
    a.account_id,
    {
      account_id: a.account_id,
      account_name: a.account_name,
      account_type: a.account_type || '',
      account_key: extractDomainFromAccountName(a.account_name || '')
    }
  ])
);

const oppsByAccount = new Map();
for (const opp of opportunities) {
  const key = opp.account_id || '';
  if (!oppsByAccount.has(key)) oppsByAccount.set(key, []);
  oppsByAccount.get(key).push({
    opportunity_id: opp.opportunity_id,
    amount: Number(opp.amount || 0),
    probability: Number(opp.probability || 0),
    opportunity_type: opp.opportunity_type || ''
  });
}

const emailsByPerson = new Map();
for (const email of emails) {
  const fromEmail = (email.from_email || '').toLowerCase().trim();
  const toEmails = splitEmails(email.to_raw);
  const ccEmails = splitEmails(email.cc_raw);
  const participants = [...new Set([fromEmail, ...toEmails, ...ccEmails].filter(Boolean))];
  const subjectLower = (email.subject || '').toLowerCase();
  const fromLower = fromEmail;
  const snippetLower = (email.snippet || '').toLowerCase();

  const isSystemEmail =
    fromLower.includes('mailer-daemon') ||
    fromLower.includes('postmaster') ||
    subjectLower.includes('delivery status notification') ||
    subjectLower.includes('security alert') ||
    subjectLower.includes('verify your identity') ||
    snippetLower.includes('address not found') ||
    snippetLower.includes('recipient address rejected') ||
    snippetLower.includes('verification code');

  if (isSystemEmail) {
    continue;
  }

  const normalized = {
    message_id: email.message_id || '',
    thread_id: email.thread_id || '',
    subject: email.subject || '',
    from_email: fromEmail,
    to_emails: toEmails,
    cc_emails: ccEmails,
    timestamp: parseDateSafe(email.timestamp),
    snippet: email.snippet || ''
  };

  for (const participant of participants) {
    if ((!emailsByPerson.has(participant))) {
      emailsByPerson.set(participant, []);                                                
    }
    emailsByPerson.get(participant).push(normalized);
  }


}

const meetingsByPerson = new Map();
for (const meeting of meetings) {
  const attendeeEmails = normalizeAttendees(meeting.attendees);

  const normalized = {
    event_id: meeting.event_id || '',
    meeting_title: meeting.meeting_title || '',
    organizer_email: (meeting.organizer_email || '').toLowerCase().trim(),
    attendee_emails: attendeeEmails,
    start_time: parseDateSafe(meeting.start_time),
    end_time: parseDateSafe(meeting.end_time),
    location: meeting.location || '',
    status: meeting.status || ''
  };

  for (const attendee of attendeeEmails) {
    if (!meetingsByPerson.has(attendee)) meetingsByPerson.set(attendee, []);
    meetingsByPerson.get(attendee).push(normalized);
  }
}

function sortDesc(arr, field) {
  return [...arr].sort((a, b) => {
    const av = a[field] ? new Date(a[field]).getTime() : 0;
    const bv = b[field] ? new Date(b[field]).getTime() : 0;
    return bv - av;
  });
}

function latestInteraction(emails, meetings) {
  const allDates = [
    ...emails.map(e => e.timestamp),
    ...meetings.map(m => m.start_time)
  ]
    .filter(Boolean)
    .map(v => new Date(v).getTime())
    .filter(v => !Number.isNaN(v));

  if (!allDates.length) return null;
  return new Date(Math.max(...allDates)).toISOString();
}

function stakeholderRole(emailCount, meetingCount, oppCount) {
  const score = emailCount * 3 + meetingCount * 5 + oppCount * 4;
  if (score >= 35) return 'high_influence';
  if (score >= 18) return 'active_stakeholder';
  if (score >= 8) return 'engaged_contact';
  return 'light_touch';
}

const output = [];

for (const contact of contacts) {
  const emailKey = (contact.contact_email || '').toLowerCase().trim();
  if (!emailKey) continue;

//   let contactEmails = [];

// Array.from(emailsByPerson, (data) => { 
//  console.log(data[0] === emailKey)
//   if (data[0] === emailKey) {
//     contactEmails.push(data);
//   }
// });
  const account = accountById.get(contact.account_id) || null;
  const contactOpps = oppsByAccount.get(contact.account_id) || [];
  const contactEmails = sortDesc(emailsByPerson.get(emailKey) || [], 'timestamp');
  const contactMeetings = sortDesc(meetingsByPerson.get(emailKey) || [], 'start_time');

  const emailCount = contactEmails.length;
  const meetingCount = contactMeetings.length;
  const opportunityCount = contactOpps.length;
  const openPipelineAmount = contactOpps.reduce((sum, o) => sum + Number(o.amount || 0), 0);
  const engagementScore = Math.min(100, emailCount * 6 + meetingCount * 10 + opportunityCount * 8);

  output.push({
    json: {
      contact_id: contact.contact_id || '',
      contact_name: contact.contact_name || '',
      contact_email: emailKey,
      account,
      opportunities: contactOpps,
      emails: contactEmails,
      meetings: contactMeetings,
      metrics: {
        email_count: emailCount,
        meeting_count: meetingCount,
        opportunity_count: opportunityCount,
        open_pipeline_amount: openPipelineAmount,
        latest_interaction_at: latestInteraction(contactEmails, contactMeetings),
        engagement_score: engagementScore,
        stakeholder_role_hint: stakeholderRole(emailCount, meetingCount, opportunityCount)
      }
    }
  });
}

return output;

const profiles = $input.all().map(i => i.json);

const nodeMap = new Map();
const edgeMap = new Map();

function addNode(id, type, data) {
  if (!id) return;
  const existing = nodeMap.get(id) || { id, type };
  nodeMap.set(id, {
    ...existing,
    ...data,
    id,
    type,
  });
}

function addEdge(from, to, relation, data = {}) {
  if (!from || !to || !relation) return;
  const key = `${from}__${relation}__${to}`;
  const existing = edgeMap.get(key) || { from, to, relation };
  edgeMap.set(key, {
    ...existing,
    ...data,
    from,
    to,
    relation,
  });
}

function safeNumber(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function safeString(value, fallback = '') {
  return value == null ? fallback : String(value);
}

function uniq(values) {
  return [...new Set(values.filter(Boolean))];
}

function normalizeOpportunityType(value) {
  const v = safeString(value).trim();
  return v || 'Unknown Opportunity Type';
}

function normalizeAccountType(value) {
  const v = safeString(value).trim();
  return v || 'Unknown';
}

function buildOpportunityDisplayName(opp) {
  const type = normalizeOpportunityType(opp.opportunity_type);
  const amount = safeNumber(opp.amount, 0);
  const probability = safeNumber(opp.probability, 0);
  return `${type} • ${amount} • ${probability}%`;
}

const accountStats = new Map();

for (const p of profiles) {
  const accountId = p.account?.account_id;
  if (!accountId) continue;

  if (!accountStats.has(accountId)) {
    accountStats.set(accountId, {
      contactIds: new Set(),
      opportunityMap: new Map(),
      total_email_count: 0,
      total_meeting_count: 0,
      latest_interaction_at: null,
    });
  }

  const stats = accountStats.get(accountId);

  if (p.contact_id) stats.contactIds.add(p.contact_id);

  stats.total_email_count += safeNumber(p.metrics?.email_count, 0);
  stats.total_meeting_count += safeNumber(p.metrics?.meeting_count, 0);

  for (const opp of p.opportunities || []) {
    const oppId = safeString(opp.opportunity_id).trim();
    if (!oppId) continue;

    if (!stats.opportunityMap.has(oppId)) {
      stats.opportunityMap.set(oppId, {
        amount: safeNumber(opp.amount, 0),
        probability: safeNumber(opp.probability, 0),
        opportunity_type: normalizeOpportunityType(opp.opportunity_type),
      });
    }
  }

  const latest = p.metrics?.latest_interaction_at;
  if (latest && (!stats.latest_interaction_at || new Date(latest) > new Date(stats.latest_interaction_at))) {
    stats.latest_interaction_at = latest;
  }
}

for (const p of profiles) {
  const contactId = `contact:${p.contact_id || p.contact_email}`;
  const accountIdRaw = p.account?.account_id || '';
  const accountId = accountIdRaw ? `account:${accountIdRaw}` : '';

  const metrics = p.metrics || {};
  const accountSummary = accountStats.get(accountIdRaw);

  let accountTotalOpenPipeline = 0;
  let accountTotalWeightedPipeline = 0;
  let accountTotalOpportunities = 0;
  let accountTotalContacts = 0;
  let accountTotalEmailCount = 0;
  let accountTotalMeetingCount = 0;

  if (accountSummary) {
    accountTotalContacts = accountSummary.contactIds.size;
    accountTotalOpportunities = accountSummary.opportunityMap.size;
    accountTotalEmailCount = accountSummary.total_email_count;
    accountTotalMeetingCount = accountSummary.total_meeting_count;

    for (const oppData of accountSummary.opportunityMap.values()) {
      const amount = safeNumber(oppData.amount, 0);
      const probability = safeNumber(oppData.probability, 0);
      accountTotalOpenPipeline += amount;
      accountTotalWeightedPipeline += Number(((amount * probability) / 100).toFixed(2));
    }
  }

  addNode(contactId, 'contact', {
    name: safeString(p.contact_name),
    email: safeString(p.contact_email).toLowerCase().trim(),
    engagement_score: safeNumber(metrics.engagement_score, 0),
    stakeholder_role_hint: safeString(metrics.stakeholder_role_hint || 'light_touch'),
    latest_interaction_at: metrics.latest_interaction_at || null,
    open_pipeline_amount: safeNumber(metrics.open_pipeline_amount, 0),
    email_count: safeNumber(metrics.email_count, 0),
    meeting_count: safeNumber(metrics.meeting_count, 0),
    opportunity_count: safeNumber(metrics.opportunity_count, 0),
    display_name: safeString(p.contact_name || p.contact_email || contactId),
  });

  if (accountId) {
    addNode(accountId, 'account', {
      name: safeString(p.account?.account_name),
      account_type: normalizeAccountType(p.account?.account_type),
      account_key: safeString(p.account?.account_key),
      total_contacts: accountTotalContacts,
      total_opportunities: accountTotalOpportunities,
      total_open_pipeline: accountTotalOpenPipeline,
      total_weighted_pipeline: accountTotalWeightedPipeline,
      total_email_count: accountTotalEmailCount,
      total_meeting_count: accountTotalMeetingCount,
      latest_interaction_at: accountSummary?.latest_interaction_at || null,
      display_name: safeString(p.account?.account_name || accountId),
    });

    addEdge(contactId, accountId, 'BELONGS_TO');
  }

  for (const opp of p.opportunities || []) {
    const oppId = opp.opportunity_id ? `opportunity:${opp.opportunity_id}` : '';
    if (!oppId) continue;

    const amount = safeNumber(opp.amount, 0);
    const probability = safeNumber(opp.probability, 0);
    const weightedAmount = Number(((amount * probability) / 100).toFixed(2));
    const oppType = normalizeOpportunityType(opp.opportunity_type);
    const oppDisplayName = buildOpportunityDisplayName(opp);

    addNode(oppId, 'opportunity', {
      name: oppDisplayName,
      display_name: oppDisplayName,
      amount,
      probability,
      weighted_amount: weightedAmount,
      opportunity_type: oppType,
    });

    addEdge(contactId, oppId, 'INVOLVED_IN', {
      amount,
      probability,
      weighted_amount: weightedAmount,
      opportunity_type: oppType,
    });

    if (accountId) {
      addEdge(accountId, oppId, 'OWNS', {
        amount,
        probability,
        weighted_amount: weightedAmount,
        opportunity_type: oppType,
      });
    }
  }

  for (const email of p.emails || []) {
    const emailId = email.message_id ? `email:${email.message_id}` : '';
    if (!emailId) continue;

    const subjectClean = safeString(email.subject).replace(/^Subject:\s*/i, '').trim() || 'No Subject';
    const toEmails = uniq((email.to_emails || []).map(v => safeString(v).toLowerCase().trim()));
    const ccEmails = uniq((email.cc_emails || []).map(v => safeString(v).toLowerCase().trim()));

    addNode(emailId, 'email', {
      subject: subjectClean,
      timestamp: email.timestamp || null,
      from_email: safeString(email.from_email).toLowerCase().trim(),
      to_emails: toEmails,
      cc_emails: ccEmails,
      snippet: safeString(email.snippet),
      display_name: subjectClean,
    });

    addEdge(contactId, emailId, 'SENT_OR_RECEIVED', {
      timestamp: email.timestamp || null,
      subject: subjectClean,
    });
  }

  for (const meeting of p.meetings || []) {
    const meetingId = meeting.event_id ? `meeting:${meeting.event_id}` : '';
    if (!meetingId) continue;

    const title = safeString(meeting.meeting_title).trim() || 'Untitled Meeting';

    addNode(meetingId, 'meeting', {
      title,
      start_time: meeting.start_time || null,
      end_time: meeting.end_time || null,
      organizer_email: safeString(meeting.organizer_email).toLowerCase().trim(),
      attendee_emails: uniq((meeting.attendee_emails || []).map(v => safeString(v).toLowerCase().trim())),
      status: safeString(meeting.status),
      location: safeString(meeting.location),
      display_name: title,
    });

    addEdge(contactId, meetingId, 'ATTENDED', {
      start_time: meeting.start_time || null,
      end_time: meeting.end_time || null,
      status: safeString(meeting.status),
    });
  }
}

return [
  {
    json: {
      generated_at: new Date().toISOString(),
      profile_count: profiles.length,
      node_count: nodeMap.size,
      edge_count: edgeMap.size,
      nodes: Array.from(nodeMap.values()),
      edges: Array.from(edgeMap.values()),
    },
  },
];
